function geoMid(low, high) {
  return Math.sqrt(low * high);
}

function product(values) {
  return values.reduce((acc, v) => acc * v, 1);
}

function allHigh(factors) {
  return factors.reduce((acc, f) => acc * f.high, 1);
}

function allLow(factors) {
  return factors.reduce((acc, f) => acc * f.low, 1);
}

function spread(factors) {
  let high = 1;
  let low = 1;
  for (const f of factors) {
    high *= f.high;
    low *= f.low;
  }
  return high / low;
}

function cornerCount(factors) {
  const ranged = factors.filter((f) => f.low !== f.high).length;
  return 2 ** ranged;
}

function looksPlausible(estimate, reference) {
  const ratio = estimate / reference;
  return ratio > 0.3 && ratio < 3;
}

function pointEstimate(factors) {
  return factors.reduce((acc, f) => {
    const mid = f.low === f.high ? f.low : Math.sqrt(f.low * f.high);
    return acc * mid;
  }, 1);
}

function cornerProducts(factors) {
  const ranged = factors.filter((f) => f.low !== f.high);
  const fixed = factors.filter((f) => f.low === f.high);
  const base = fixed.reduce((acc, f) => acc * f.low, 1);
  const results = [];
  for (let mask = 0; mask < 2 ** ranged.length; mask++) {
    let product = base;
    for (let i = 0; i < ranged.length; i++) {
      product *= (mask >> i) & 1 ? ranged[i].high : ranged[i].low;
    }
    results.push(product);
  }
  return results.sort((a, b) => a - b);
}

function shareWithin(values, center, factor) {
  const inside = values.filter(
    (v) => v >= center / factor && v <= center * factor,
  );
  return inside.length / values.length;
}

function referenceCheck(estimate, referencePrediction) {
  const ratio = estimate / referencePrediction;
  return { ratio, plausible: ratio > 0.3 && ratio < 3 };
}
